-- ═══════════════════════════════════════════════════════════════════════════
--  IRC PLATFORM — FULL DATABASE BOOTSTRAP (PostgreSQL)
--
--  This file is a single, self-contained import script:
--   1. DROP block      — wipes any prior IRC tables/sequences (optional)
--   2. SEQUENCES       — creates research_irc_seq (used by ResearchService)
--   3. SCHEMA          — every table, FK, constraint, index for the app
--                        (generated by Hibernate's SchemaCreator against the
--                         current JPA entities; PostgreSQL dialect)
--   4. SEED DATA       — mock users, posts, researches, etc. — idempotent
--                        (every INSERT uses ON CONFLICT DO NOTHING)
--
--  Usage:
--     psql -h <host> -U <user> -d <db> -f db/irc_full.sql
--  or, from inside psql:
--     \i db/irc_full.sql
--
--  Re-import safety:
--   - Section 1 wipes the schema completely before recreating it. Comment it
--     out if you are appending to an existing database that already has data.
--   - The seed section is fully idempotent (ON CONFLICT DO NOTHING).
-- ═══════════════════════════════════════════════════════════════════════════


-- ═══════════════════════════════════════════════════════════════════════════
--  1. DROP BLOCK — wipes the schema for a clean reimport.
--     Comment this whole DO block out if you don't want a clean wipe.
-- ═══════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
    r RECORD;
BEGIN
    -- Drop every table the application owns. CASCADE catches FK chains and
    -- the audit-trigger / generated-column dependencies the schema relies on.
    FOR r IN
        SELECT tablename FROM pg_tables WHERE schemaname = current_schema()
    LOOP
        EXECUTE format('DROP TABLE IF EXISTS %I CASCADE', r.tablename);
    END LOOP;

    -- Drop our named sequence (the rest are owned by tables and went with them).
    EXECUTE 'DROP SEQUENCE IF EXISTS research_irc_seq CASCADE';
END $$;


-- ═══════════════════════════════════════════════════════════════════════════
--  2. SEQUENCES — must exist before SchemaCreator's seeds reference them.
--     ResearchServiceImpl.create() does `SELECT nextval('research_irc_seq')`
--     for every new paper; Hibernate doesn't create this sequence because no
--     JPA generator owns it (we issue a native query).
--
--     Start at 100 so the 6 seeded research rows below (numbers 1–6) keep
--     their fixed IRC-2024-00000N identifiers and new uploads pick up from
--     100 onward.
-- ═══════════════════════════════════════════════════════════════════════════

CREATE SEQUENCE IF NOT EXISTS research_irc_seq
    START WITH 100
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


-- ═══════════════════════════════════════════════════════════════════════════
--  3. SCHEMA — every table, FK, constraint, index.
--     Generated by Hibernate SchemaCreator from the JPA entities under
--     ak.dev.irc.app.*.entity. Regenerate with:
--         ./mvnw -o test -Dtest=SchemaExporter -DfailIfNoTests=false
--     Output lands at target/generated-schema.sql.
-- ═══════════════════════════════════════════════════════════════════════════


    create table answer_attachments (
        id uuid not null,
        action_note varchar(500),
        created_at timestamp(6) not null,
        created_by uuid,
        created_by_device varchar(300),
        created_by_ip varchar(45),
        last_action varchar(30) check (last_action in ('CREATE','UPDATE','DELETE','LOGIN','LOGOUT','FOLLOW','UNFOLLOW','BLOCK','UNBLOCK','RESTRICT','UNRESTRICT','UPLOAD','PASSWORD_CHANGE','EMAIL_VERIFY','TOKEN_REFRESH')),
        updated_at timestamp(6) not null,
        updated_by uuid,
        updated_by_device varchar(300),
        updated_by_ip varchar(45),
        caption varchar(500),
        display_order integer not null,
        duration_seconds integer,
        file_size bigint not null,
        file_url TEXT not null,
        media_type varchar(20) not null check (media_type in ('IMAGE','VIDEO','AUDIO','DOCUMENT','SPREADSHEET','DATASET','CODE','ARCHIVE','OTHER')),
        mime_type varchar(100) not null,
        original_file_name varchar(500) not null,
        s3_key TEXT not null,
        thumbnail_s3_key TEXT,
        thumbnail_url TEXT,
        answer_id uuid not null,
        primary key (id)
    );

